*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

/* ─── Tokens ───────────────────────────────────────────────────────── */
:root {
  --bg-page:        #0f1117;
  --bg-card:        #1a1d27;
  --bg-input:       #12141e;
  --border-default: #2e3149;
  --border-focus:   #7c83ff;
  --border-error:   #ff6b6b;
  --text-primary:   #e8eaf6;
  --text-secondary: #9499c4;
  --text-label:     #c5c8e8;
  --text-error:     #ff8a8a;
  --text-help:      #8b90b8;
  --accent:         #7c83ff;
  --accent-hover:   #9298ff;
  --required:       #ff8a8a;
  --radius:         6px;
  --gap:            1.5rem;
}

/* ─── Visually hidden utility ──────────────────────────────────────── */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
}

/* ─── Skip link ────────────────────────────────────────────────────── */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  z-index: 9999;
  padding: 0.5rem 1rem;
  background: var(--accent);
  color: #fff;
  font-weight: 600;
  border-radius: var(--radius);
  text-decoration: none;
  transition: top 0.1s;
}
.skip-link:focus {
  top: 1rem;
}

/* ─── Page shell ───────────────────────────────────────────────────── */
body {
  background-color: var(--bg-page);
  color: var(--text-primary);
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  font-size: 1rem;
  line-height: 1.6;
  min-height: 100dvh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 2rem 1rem;
}

main {
  width: 100%;
  max-width: 520px;
}

/* ─── Card ─────────────────────────────────────────────────────────── */
.form-card {
  background: var(--bg-card);
  border: 1px solid var(--border-default);
  border-radius: 12px;
  padding: 2.5rem 2rem;
}

h1 {
  font-size: 1.65rem;
  font-weight: 700;
  color: var(--text-primary);
  margin-bottom: 0.35rem;
}

.form-intro {
  font-size: 0.875rem;
  color: var(--text-secondary);
  margin-bottom: 2rem;
}

/* ─── Status (success) message ─────────────────────────────────────── */
.form-status {
  border-radius: var(--radius);
  font-size: 0.9rem;
  font-weight: 500;
}
.form-status:not(:empty) {
  padding: 0.75rem 1rem;
  margin-bottom: 1.25rem;
  background: #1a2e1a;
  border: 1px solid #3a6b3a;
  color: #7ecb7e;
}

/* ─── Form layout ──────────────────────────────────────────────────── */
form {
  display: flex;
  flex-direction: column;
  gap: var(--gap);
}

/* ─── Form field ───────────────────────────────────────────────────── */
.form-field {
  display: flex;
  flex-direction: column;
  gap: 0.3rem;
}

/* ─── Label ────────────────────────────────────────────────────────── */
label {
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--text-label);
  display: flex;
  align-items: baseline;
  gap: 0.3rem;
}

.required-marker {
  color: var(--required);
  font-size: 1rem;
  line-height: 1;
}

.optional-label {
  font-weight: 400;
  font-size: 0.8rem;
  color: var(--text-secondary);
}

/* ─── Input ────────────────────────────────────────────────────────── */
input {
  background: var(--bg-input);
  border: 1px solid var(--border-default);
  border-radius: var(--radius);
  color: var(--text-primary);
  font-size: 0.95rem;
  padding: 0.65rem 0.85rem;
  width: 100%;
  transition: border-color 0.15s, box-shadow 0.15s;
  outline: none;
}

input::placeholder {
  color: var(--text-help);
}

input:focus {
  border-color: var(--border-focus);
  box-shadow: 0 0 0 3px rgba(124, 131, 255, 0.25);
}

input[aria-invalid="true"] {
  border-color: var(--border-error);
}

input[aria-invalid="true"]:focus {
  box-shadow: 0 0 0 3px rgba(255, 107, 107, 0.25);
}

/* ─── Help & error text ────────────────────────────────────────────── */
.field-help {
  font-size: 0.8rem;
  color: var(--text-help);
  line-height: 1.4;
}

.field-error {
  font-size: 0.8rem;
  color: var(--text-error);
  font-weight: 500;
  line-height: 1.4;
}

.field-error[hidden] {
  display: none;
}

/* ─── Submit button ────────────────────────────────────────────────── */
button[type="submit"] {
  align-self: flex-start;
  background: var(--accent);
  border: none;
  border-radius: var(--radius);
  color: #fff;
  cursor: pointer;
  font-size: 0.95rem;
  font-weight: 600;
  padding: 0.7rem 1.75rem;
  transition: background 0.15s, box-shadow 0.15s;
  margin-top: 0.5rem;
}

button[type="submit"]:hover {
  background: var(--accent-hover);
}

button[type="submit"]:focus-visible {
  outline: 3px solid var(--border-focus);
  outline-offset: 3px;
}

/* ─── Forced colors (Windows High Contrast) ───────────────────────── */
@media (forced-colors: active) {
  input {
    border: 2px solid ButtonText;
    background: Field;
    color: FieldText;
  }
  input:focus {
    outline: 2px solid Highlight;
  }
  button[type="submit"] {
    forced-color-adjust: auto;
  }
  .field-error {
    color: Mark;
  }
}

/* ─── Reflow: narrow viewports ─────────────────────────────────────── */
@media (max-width: 400px) {
  .form-card {
    padding: 1.5rem 1rem;
  }
  button[type="submit"] {
    width: 100%;
    align-self: stretch;
  }
}
