// Find a dark-enough indigo that gives >=4.5:1 with white
function srgb(c) { c/=255; return c<=0.04045 ? c/12.92 : Math.pow((c+0.055)/1.055,2.4); }
function lum(r,g,b){ return 0.2126*srgb(r)+0.7152*srgb(g)+0.0722*srgb(b); }
function contrast(l1,l2){ const[a,b]=[Math.max(l1,l2),Math.min(l1,l2)]; return (a+0.05)/(b+0.05); }
const wl = lum(255,255,255);
// Try #5558d6
const candidates = ['#5558d6','#5254cc','#4e51c8','#5b5fc7','#5055d0'];
for (const hex of candidates) {
  const r=parseInt(hex.slice(1,3),16), g=parseInt(hex.slice(3,5),16), b=parseInt(hex.slice(5,7),16);
  console.log(hex, 'contrast:', contrast(wl, lum(r,g,b)).toFixed(2));
}
