<body>
  <a class="skip-link" href="#main">Skip to main content</a>

  <main id="main">
    <div class="form-card">
      <h1>Contact Support</h1>
      <p class="form-intro">Fields marked <span aria-hidden="true">*</span><span class="sr-only">with an asterisk</span> are required.</p>

      <!-- Live region: success message (rendered empty; text injected by JS) -->
      <div role="status" id="form-status" class="form-status"></div>

      <form id="contact-form" novalidate>

        <div class="form-field">
          <label for="full-name">
            Full name <span aria-hidden="true" class="required-marker">*</span>
          </label>
          <input
            id="full-name"
            name="full-name"
            type="text"
            autocomplete="name"
            required
            aria-required="true"
            aria-describedby="full-name-error"
          >
          <p id="full-name-error" class="field-error" hidden></p>
        </div>

        <div class="form-field">
          <label for="email">
            Email address <span aria-hidden="true" class="required-marker">*</span>
          </label>
          <input
            id="email"
            name="email"
            type="email"
            autocomplete="email"
            required
            aria-required="true"
            aria-describedby="email-error"
          >
          <p id="email-error" class="field-error" hidden></p>
        </div>

        <div class="form-field">
          <label for="phone">
            Phone number <span class="optional-label">(optional)</span>
          </label>
          <input
            id="phone"
            name="phone"
            type="tel"
            autocomplete="tel"
            aria-describedby="phone-help phone-error"
          >
          <p id="phone-help" class="field-help">Enter digits only, e.g. 4155552671 or include country code like +14155552671.</p>
          <p id="phone-error" class="field-error" hidden></p>
        </div>

        <button type="submit" id="submit-btn">Send message</button>

      </form>
    </div>
  </main>

  <script>
(function () {
  'use strict';

  const form     = document.getElementById('contact-form');
  const statusEl = document.getElementById('form-status');

  const fields = {
    fullName: {
      input:    document.getElementById('full-name'),
      errorEl:  document.getElementById('full-name-error'),
      validate: validateFullName,
    },
    email: {
      input:    document.getElementById('email'),
      errorEl:  document.getElementById('email-error'),
      validate: validateEmail,
    },
    phone: {
      input:    document.getElementById('phone'),
      errorEl:  document.getElementById('phone-error'),
      validate: validatePhone,
    },
  };

  /* ── Validators ─────────────────────────────────────────────────── */

  function validateFullName(value) {
    if (!value.trim()) return 'Error: Full name is required.';
    return null;
  }

  function validateEmail(value) {
    if (!value.trim()) return 'Error: Email address is required.';
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value.trim())) {
      return 'Error: Enter a valid email address, e.g. name@example.com.';
    }
    return null;
  }

  function validatePhone(value) {
    if (!value.trim()) return null;
    if (!/^\+?\d{7,15}$/.test(value.trim())) {
      return 'Error: Enter digits only (7\u201315), optionally starting with +, e.g. 4155552671 or +14155552671.';
    }
    return null;
  }

  /* ── Show / clear error ─────────────────────────────────────────── */

  function showError(field, message) {
    field.errorEl.textContent = message;
    field.errorEl.hidden = false;
    field.input.setAttribute('aria-invalid', 'true');
  }

  function clearError(field) {
    field.errorEl.textContent = '';
    field.errorEl.hidden = true;
    field.input.removeAttribute('aria-invalid');
  }

  /* ── Live validation on blur ────────────────────────────────────── */

  Object.values(fields).forEach(function (field) {
    field.input.addEventListener('blur', function () {
      const error = field.validate(field.input.value);
      if (error) { showError(field, error); } else { clearError(field); }
    });

    field.input.addEventListener('input', function () {
      if (field.input.getAttribute('aria-invalid') === 'true') {
        const error = field.validate(field.input.value);
        if (error) { showError(field, error); } else { clearError(field); }
      }
    });
  });

  /* ── Submit ─────────────────────────────────────────────────────── */

  form.addEventListener('submit', function (event) {
    event.preventDefault();
    statusEl.textContent = '';

    let firstInvalidField = null;

    Object.values(fields).forEach(function (field) {
      const error = field.validate(field.input.value);
      if (error) {
        showError(field, error);
        if (!firstInvalidField) firstInvalidField = field;
      } else {
        clearError(field);
      }
    });

    if (firstInvalidField) {
      firstInvalidField.input.focus();
      return;
    }

    form.reset();
    Object.values(fields).forEach(clearError);
    statusEl.textContent = 'Your message has been sent. We\u2019ll get back to you shortly.';
  });
})();
