    if (!value.trim()) return 'Error: Email address is required.';
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value.trim())) {
      return 'Error: Enter a valid email address, e.g. name@example.com.';
    }
    return null;
